<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#ffc928"><link rel="manifest" href="manifest.json"><link rel="stylesheet" href="css/style.css"><link rel="stylesheet" href="css/responsive.css"><link rel="apple-touch-icon" href="assets/icons/icon-192.svg"><title>Product Details</title></head><body><main class="app"><div id="top"></div><section class="detail" id="detail"></section></main><div class="toast"></div><div class="sheet" onclick="if(event.target===this)this.classList.remove('show')"><div><h2>Install this app on your iPhone</h2><p>1. Tap the Share button in Safari.<br><br>2. Select <b>Add to Home Screen</b>.<br><br>3. Tap <b>Add</b>.</p><button class="primary" onclick="this.closest('.sheet').classList.remove('show')">Got it</button></div></div><script src="js/products.js"></script><script src="js/app.js"></script><script src="js/cart.js"></script><script src="js/pwa.js"></script><script>let id=new URLSearchParams(location.search).get('id')||'biryani',p=PRODUCTS.find(x=>x.id===id)||PRODUCTS[0];$('#top').innerHTML=top('Product Details',true);let qty=1;function draw(){let fav=favorites().includes(p.id);$('#detail').innerHTML=`<div style="position:relative"><img class="detail-img" src="assets/images/${p.id}.svg" alt="${p.name}"><button class="heart ${fav?'on':''}" id="fav">${fav?'♥':'♡'}</button></div><h1>${p.name}</h1><div class="meta"><span>★ ${p.rating}</span><span>${p.reviews} reviews</span><span>${p.time}</span></div><div class="price" style="font-size:24px">$${p.price.toFixed(2)}</div><p class="desc">${p.desc}</p><h3>Quantity</h3><div class="qty"><button id="minus">−</button><b>${qty}</b><button id="plus">+</button></div><h3>Optional extras</h3><div class="extras"><label>Extra cheese <input type="checkbox" value="Extra cheese"></label><label>Extra sauce <input type="checkbox" value="Extra sauce"></label><label>Extra meat <input type="checkbox" value="Extra meat"></label></div><div class="sticky-cta"><button class="primary" id="add">Add to Cart — $${(p.price*qty).toFixed(2)}</button></div>`;$('#fav').onclick=()=>{toggleFav(p.id);draw()};$('#minus').onclick=()=>{qty=Math.max(1,qty-1);draw()};$('#plus').onclick=()=>{qty++;draw()};$('#add').onclick=()=>addCart(p.id,qty,$$('input:checked').map(x=>x.value))}draw();renderBadges();</script></body></html>